		name  string
		cur   string
		count int
		total int64
		want  int64
	}{
		{"no charges", "USD", 0, 0, 0},
		{"one charge", "USD", 1, 10_000, 290},
		{"ten charges", "USD", 10, 50_000, 1453},
		{"usd minimum", "USD", 1, 100, 30},
		{"krw minimum", "KRW", 1, 1_000, 300},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := CalculateFee(DefaultSchedule, tc.cur, tc.count, tc.total)
			if got != tc.want {
				t.Errorf("CalculateFee = %d, want %d", got, tc.want)
			}
		})
	}
}

// 2.90% of 100.15 is 2.90435 and the per-entry part is 0.3, so the fee is 2.91.
// The two parts are added before rounding; rounding each part first gives 2.90.
func TestCalculateFeeRoundsPartsTogether(t *testing.T) {
	got := CalculateFee(DefaultSchedule, "USD", 1, 10_015)
	if got != 291 {
		t.Errorf("CalculateFee(10015) = %d, want 291", got)
	}
}
package domain

import (
	"errors"
	"fmt"
	"testing"
	"time"
)

var (
	start = time.Date(2025, 5, 1, 0, 0, 0, 0, time.UTC)
	end   = time.Date(2025, 6, 1, 0, 0, 0, 0, time.UTC)
	key   = []byte("test-signing-key")
)

func entry(id string, kind Kind, amount int64, cur string, day int) Entry {
	return Entry{
		ID: id, UserID: "u_1", Kind: kind, AmountMinor: amount, Currency: cur,
		IdempotencyKey: id, CreatedAt: start.AddDate(0, 0, day),
	}
}

func input(cur string, entries ...Entry) CloseInput {
	return CloseInput{
		ID: "stl_1", UserID: "u_1", Currency: cur, Start: start, End: end,
		Entries: entries, Schedule: DefaultSchedule, SigningKey: key, Now: end,
	}
}

func TestCloseTotals(t *testing.T) {
	s, err := Close(input("USD",
		entry("a", KindCharge, 10_000, "USD", 1),
		entry("b", KindRefund, 1_500, "USD", 2),
		entry("c", KindAdjustment, -200, "USD", 3),
	))
	if err != nil {
		t.Fatal(err)
	}
	// Fee is 2.90% of 100.00 plus 0.3 cents: 290.3 rounds to 290.
	want := Settlement{ChargesMinor: 10_000, RefundsMinor: 1_500, AdjustmentsMinor: -200,
		FeeMinor: 290, RoundingMinor: 0, TotalMinor: 8_590, EntryCount: 3}
	if s.ChargesMinor != want.ChargesMinor || s.RefundsMinor != want.RefundsMinor ||
		s.AdjustmentsMinor != want.AdjustmentsMinor || s.FeeMinor != want.FeeMinor ||
		s.RoundingMinor != want.RoundingMinor || s.TotalMinor != want.TotalMinor ||
		s.EntryCount != want.EntryCount || s.Status != StatusClosed {
		t.Fatalf("settlement = %+v, want %+v", s, want)
	}
}

func TestCloseRoundsToCurrencyIncrement(t *testing.T) {
	// KRW settles in 10 won. 3,500 charge: fee 101.5 -> floor-free minimum is 300.
	// due = 3,500 + 300 = 3,800, already a multiple of 10.
	s, err := Close(input("KRW", entry("a", KindCharge, 3_500, "KRW", 1)))
	if err != nil {
		t.Fatal(err)
	}
	if s.FeeMinor != 300 || s.TotalMinor != 3_800 || s.RoundingMinor != 0 {
		t.Fatalf("settlement = %+v", s)
	}
	// A refund-only period has no fee; 1,234 won owed back rounds to 1,230.
	s, err = Close(input("KRW", entry("b", KindRefund, 1_234, "KRW", 1)))
	if err != nil {
		t.Fatal(err)
	}
	if s.FeeMinor != 0 || s.TotalMinor != -1_230 || s.RoundingMinor != 4 {
		t.Fatalf("settlement = %+v", s)
	}
}

func TestCloseErrors(t *testing.T) {
	good := entry("a", KindCharge, 10_000, "USD", 1)
	tests := []struct {
		name   string
		mutate func(*CloseInput)
		want   error
	}{
		{"bad currency", func(in *CloseInput) { in.Currency = "XXX" }, ErrBadCurrency},
		{"bad period", func(in *CloseInput) { in.End = in.Start }, ErrBadPeriod},
		{"nothing", func(in *CloseInput) { in.Entries = nil }, ErrNothingToSettle},
		{"wrong user", func(in *CloseInput) {
			in.Entries = []Entry{{ID: "x", UserID: "other", Kind: KindCharge, AmountMinor: 1, Currency: "USD", CreatedAt: start}}
		}, ErrEntryMismatch},
		{"wrong currency", func(in *CloseInput) { in.Entries = []Entry{entry("x", KindCharge, 1, "EUR", 1)} }, ErrEntryMismatch},
		{"outside period", func(in *CloseInput) { in.Entries = []Entry{entry("x", KindCharge, 1, "USD", 40)} }, ErrEntryMismatch},
		{"already locked", func(in *CloseInput) { e := good; e.SettlementID = "stl_0"; in.Entries = []Entry{e} }, ErrEntryMismatch},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			in := input("USD", good)
			tc.mutate(&in)
			if _, err := Close(in); !errors.Is(err, tc.want) {
				t.Fatalf("Close() = %v, want %v", err, tc.want)
			}
		})
	}
}

func TestSignatureDetectsTampering(t *testing.T) {
	s, err := Close(input("USD", entry("a", KindCharge, 10_000, "USD", 1)))
	if err != nil {
		t.Fatal(err)
	}
	if !Verify(key, s) {
		t.Fatal("fresh settlement must verify")
	}
	if Verify([]byte("other-key"), s) {
		t.Fatal("wrong key must not verify")
	}
	s.TotalMinor--
	if Verify(key, s) {
		t.Fatal("changed total must not verify")
	}
}

func TestChunk(t *testing.T) {
	var in []Entry
	for i := 0; i < 7; i++ {
		in = append(in, Entry{ID: fmt.Sprint(i)})
	}
	got := Chunk(in, 3)
	if len(got) != 3 || len(got[0]) != 3 || len(got[2]) != 1 || got[2][0].ID != "6" {
		t.Fatalf("Chunk = %v", got)
	}
	if len(Chunk(nil, 3)) != 0 {
		t.Fatal("empty input must give no batches")
	}
	if len(Chunk(in, 0)) != 1 {
		t.Fatal("non-positive size must fall back to the default")
	}
}
// Package domain holds the pure business rules of the ledger: entries, fee
// calculation, rounding and settlement. It performs no I/O.
//
// All money is an int64 in the minor unit of the entry's currency (cents for USD,
// won for KRW, fils for KWD).
package domain

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// Kind classifies a ledger entry.
type Kind string

const (
	// KindCharge is an amount the user owes, for example a shipping charge.
	KindCharge Kind = "charge"
	// KindRefund reduces what the user owes.
	KindRefund Kind = "refund"
	// KindAdjustment is a manual correction; its amount keeps its own sign.
	KindAdjustment Kind = "adjustment"
)

// Valid reports whether k is a known kind.
func (k Kind) Valid() bool {
	return k == KindCharge || k == KindRefund || k == KindAdjustment
}

// Entry is one line in a user's ledger.
type Entry struct {
	ID             string    `json:"id"`
	UserID         string    `json:"user_id"`
	SettlementID   string    `json:"settlement_id,omitempty"`
	Kind           Kind      `json:"kind"`
	AmountMinor    int64     `json:"amount_minor"`
	Currency       string    `json:"currency"`
	IdempotencyKey string    `json:"idempotency_key"`
	Memo           string    `json:"memo,omitempty"`
	CreatedAt      time.Time `json:"created_at"`
}

// Validation errors returned by Entry.Validate.
var (
	ErrNoUser         = errors.New("user_id is required")
	ErrBadKind        = errors.New("kind must be charge, refund or adjustment")
	ErrBadAmount      = errors.New("invalid amount")
	ErrBadCurrency    = errors.New("unsupported currency")
	ErrBadKey         = errors.New("idempotency_key must be 1 to 128 characters")
	ErrMemoTooLong    = errors.New("memo must be at most 200 characters")
	ErrFutureEntry    = errors.New("created_at is in the future")
	maxClockSkew      = 5 * time.Minute
	maxIdempotencyKey = 128
	maxMemo           = 200
)

// Validate checks the invariants every stored entry must satisfy.
func (e Entry) Validate(now time.Time) error {
	if strings.TrimSpace(e.UserID) == "" {
		return ErrNoUser
	}
	if !e.Kind.Valid() {
		return fmt.Errorf("%w: %q", ErrBadKind, e.Kind)
	}
	switch e.Kind {
	case KindCharge, KindRefund:
		if e.AmountMinor <= 0 {
			return fmt.Errorf("%w: %s must be positive", ErrBadAmount, e.Kind)
		}
	case KindAdjustment:
		if e.AmountMinor == 0 {
			return fmt.Errorf("%w: adjustment must not be zero", ErrBadAmount)
		}
	}
	if !Supported(e.Currency) {
		return fmt.Errorf("%w: %q", ErrBadCurrency, e.Currency)
	}
	if n := len(e.IdempotencyKey); n < 1 || n > maxIdempotencyKey {
		return ErrBadKey
	}
	if len(e.Memo) > maxMemo {
		return ErrMemoTooLong
	}
	if !e.CreatedAt.IsZero() && e.CreatedAt.After(now.Add(maxClockSkew)) {
		return ErrFutureEntry
	}
	return nil
}

// SignedMinor is the effect of the entry on what the user owes: charges add,
// refunds subtract, adjustments apply as stored.
func (e Entry) SignedMinor() int64 {
	if e.Kind == KindRefund {
		return -e.AmountMinor
	}
	return e.AmountMinor
}

// SamePayload reports whether two entries describe the same request, ignoring the
// fields the store assigns. It decides whether a repeated idempotency key is a
// replay or a conflict.
func (e Entry) SamePayload(o Entry) bool {
	return e.UserID == o.UserID && e.Kind == o.Kind && e.AmountMinor == o.AmountMinor &&
		e.Currency == o.Currency && e.Memo == o.Memo
}

// Balances sums the signed amounts of entries per currency.
func Balances(entries []Entry) map[string]int64 {
	out := make(map[string]int64)
	for _, e := range entries {
		out[e.Currency] += e.SignedMinor()
	}
	return out
}
package domain

// RoundDiv divides n by d (d > 0) and rounds half away from zero.
func RoundDiv(n, d int64) int64 {
	if n >= 0 {
		return (n + d/2) / d
	}
	return -((-n + d/2) / d)
}

// RoundToIncrement rounds amount to the nearest multiple of inc, half away from
// zero. An increment of 1 or less leaves the amount unchanged.
func RoundToIncrement(amount, inc int64) int64 {
	if inc <= 1 {
		return amount
	}
	return RoundDiv(amount, inc) * inc
}

